class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        batch_size, channels, height, width = x.shape
        k = self.kernel_size
        s = self.stride
        p = self.padding
        d = self.dilation
        height_out = (height + 2 * p - d * (k - 1) - 1) // s + 1
        width_out = width + 2 * p

        out = torch.empty((batch_size, channels, height_out, width_out), device=x.device, dtype=x.dtype)

        weight = self.conv2d.weight
        bias_tensor = self.conv2d.bias
        has_bias = 1 if bias_tensor is not None else 0
        bias_arg = bias_tensor if bias_tensor is not None else weight

        block_x = 64
        tile_h = 64
        grid_x = (width_out + block_x - 1) // block_x
        grid_y = (height_out + tile_h - 1) // tile_h
        module.launch(
            "depthwise_conv_k1",
            grid=(grid_x, grid_y, batch_size * channels),
            block=(16, 16, 1),
            arguments=[
                x,
                weight,
                bias_arg,
                out,
                u32(channels),
                u32(height),
                u32(width),
                u32(height_out),
                u32(width_out),
                u32(k),
                u32(s),
                u32(p),
                u32(d),
                u32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

